 37→type Agent interface {
 38→	Name() string
 39→	// Binary returns the CLI binary name (e.g. "claude", "gemini").
 40→	Binary() string
 41→	EntireAgent() string
 42→	PromptPattern() string
 43→	// TimeoutMultiplier returns a factor applied to per-test timeouts.
 44→	// Slower agents (e.g. Gemini) return values > 1.
 45→	TimeoutMultiplier() float64
 46→	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
 47→	StartSession(ctx context.Context, dir string) (Session, error)
 48→	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
 49→	// Called before any tests run. Implementations should be idempotent.
 50→	Bootstrap() error
 51→	// IsTransientError returns true if the error from RunPrompt looks like
 52→	// a transient API failure (e.g. 500, rate limit, network error) that
 53→	// is worth retrying.
 54→	IsTransientError(out Output, err error) bool
 55→}
 56→
 57→type Session interface {
 58→	Send(input string) error
 59→	WaitFor(pattern string, timeout time.Duration) (string, error)
 60→	Capture() string
 61→	Close() error
 62→}
 63→
 64→var registry []Agent
 65→var gates = map[string]chan struct{}{}
 66→
 67→func Register(a Agent) {
 68→	registry = append(registry, a)
 69→}
 70→
 71→// RegisterGate sets a concurrency limit for an agent's tests.
 72→// Tests call AcquireSlot/ReleaseSlot to respect this limit.
 73→// The limit can be overridden via E2E_CONCURRENT_TEST_LIMIT.
 74→func RegisterGate(name string, defaultMax int) {
 75→	max := defaultMax
 76→	if v, err := strconv.Atoi(os.Getenv("E2E_CONCURRENT_TEST_LIMIT")); err == nil && v > 0 {
 77→		max = v
 78→	}
 79→	gates[name] = make(chan struct{}, max)
 80→}
 81→
 82→// AcquireSlot blocks until a test slot is available for the agent or the
 83→// context is cancelled. Returns a non-nil error if the context expires
 84→// before a slot opens.
 85→func AcquireSlot(ctx context.Context, a Agent) error {
 86→	g, ok := gates[a.Name()]
 87→	if !ok {
 88→		return nil
 89→	}
 90→	select {
 91→	case g <- struct{}{}:
 92→		return nil
 93→	case <-ctx.Done():
 94→		return ctx.Err()
 95→	}
 96→}
 97→
 98→// ReleaseSlot frees a test slot for the agent.
 99→func ReleaseSlot(a Agent) {
100→	if g, ok := gates[a.Name()]; ok {
101→		<-g
102→	}
103→}
104→
105→func All() []Agent {
106→	return registry
107→}
108→
109→// filterEnv returns env with entries matching any of the given variable names
110→// removed. Used to strip test-only overrides (e.g. ENTIRE_TEST_TTY) from agent
111→// processes so they exercise real detection paths.
112→func filterEnv(env []string, names ...string) []string {
113→	out := make([]string, 0, len(env))
114→	for _, e := range env {
115→		skip := false
116→		for _, name := range names {
117→			if strings.HasPrefix(e, name+"=") {
118→				skip = true
119→				break
120→			}
121→		}
122→		if !skip {
123→			out = append(out, e)
124→		}
125→	}
126→	return out
127→}
