138→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
139→	cfg := &runConfig{Model: defaultDroidModel}
140→	for _, o := range opts {
141→		o(cfg)
142→	}
143→
144→	model := cfg.Model
145→	if model == "" {
146→		model = defaultDroidModel
147→	}
148→
149→	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
150→	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
151→
152→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
153→	cmd.Dir = dir
154→	cmd.Stdin = nil
155→	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CI", "GITHUB_ACTIONS")
156→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
157→	cmd.Cancel = func() error {
158→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
159→	}
160→	cmd.WaitDelay = 5 * time.Second
161→
162→	var stdout, stderr strings.Builder
163→	cmd.Stdout = &stdout
164→	cmd.Stderr = &stderr
165→
166→	err := cmd.Run()
167→	exitCode := 0
168→	if err != nil {
169→		exitErr := &exec.ExitError{}
170→		if errors.As(err, &exitErr) {
171→			exitCode = exitErr.ExitCode()
172→		} else {
173→			exitCode = -1
174→		}
175→	}
176→
177→	return Output{
178→		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
179→		Stdout:   stdout.String(),
180→		Stderr:   stderr.String(),
181→		ExitCode: exitCode,
182→	}, err
183→}
184→
185→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
186→	name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
187→	// Unset CI and GITHUB_ACTIONS so Droid doesn't enter single-turn/headless
188→	// mode — it checks these vars and skips interactive input after the first turn.
189→	s, err := NewTmuxSession(name, dir, []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}, d.Binary())
190→	if err != nil {
191→		return nil, err
192→	}
193→
194→	// Wait for the interactive prompt indicator.
195→	if _, err := s.WaitFor(`>`, 30*time.Second); err != nil {
196→		_ = s.Close()
197→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
198→	}
199→
200→	// Droid auto-generates a greeting on startup which fires a Stop hook.
201→	// Wait for the greeting turn to fully complete before accepting prompts.
202→	select {
203→	case <-ctx.Done():
204→		_ = s.Close()
205→		return nil, fmt.Errorf("context cancelled during startup wait: %w", ctx.Err())
206→	case <-time.After(2 * time.Second):
207→	}
208→	s.stableAtSend = ""
209→
210→	return s, nil
211→}
