115→// ReadSession reads a session from Factory AI Droid's storage (JSONL transcript file).
116→// The session data is stored in NativeData as raw JSONL bytes.
117→// ModifiedFiles is computed by parsing the transcript.
118→func (f *FactoryAIDroidAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
119→	if input.SessionRef == "" {
120→		return nil, errors.New("session reference (transcript path) is required")
121→	}
122→
123→	data, err := os.ReadFile(input.SessionRef)
124→	if err != nil {
125→		return nil, fmt.Errorf("failed to read transcript: %w", err)
126→	}
127→
128→	lines, _, err := ParseDroidTranscriptFromBytes(data, 0)
129→	if err != nil {
130→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
131→	}
132→
133→	return &agent.AgentSession{
134→		SessionID:     input.SessionID,
135→		AgentName:     f.Name(),
136→		SessionRef:    input.SessionRef,
137→		StartTime:     time.Now(),
138→		NativeData:    data,
139→		ModifiedFiles: ExtractModifiedFiles(lines),
140→	}, nil
141→}
142→
143→// WriteSession writes a session to Factory AI Droid's storage (JSONL transcript file).
144→// Uses the NativeData field which contains raw JSONL bytes.
145→func (f *FactoryAIDroidAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
146→	if session == nil {
147→		return errors.New("session is nil")
148→	}
149→
150→	if session.AgentName != "" && session.AgentName != f.Name() {
151→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, f.Name())
152→	}
153→
154→	if session.SessionRef == "" {
155→		return errors.New("session reference (transcript path) is required")
156→	}
157→
158→	if len(session.NativeData) == 0 {
159→		return errors.New("session has no native data to write")
160→	}
161→
162→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
163→		return fmt.Errorf("failed to create session directory: %w", err)
164→	}
165→
166→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
167→		return fmt.Errorf("failed to write transcript: %w", err)
168→	}
169→
170→	return nil
171→}
