166→func (f *FactoryAIDroidAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
167→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
168→	if err != nil {
169→		return nil, err
170→	}
171→	return &agent.Event{
172→		Type:       agent.SessionStart,
173→		SessionID:  raw.SessionID,
174→		SessionRef: raw.TranscriptPath,
175→		Timestamp:  time.Now(),
176→	}, nil
177→}
