179→func (f *FactoryAIDroidAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
180→	raw, err := agent.ReadAndParseHookInput[userPromptSubmitRaw](stdin)
181→	if err != nil {
182→		return nil, err
183→	}
184→	return &agent.Event{
185→		Type:       agent.TurnStart,
186→		SessionID:  raw.SessionID,
187→		SessionRef: raw.TranscriptPath,
