// Package fakeagent implements the Agent interface for a deterministic fake agent
// used as an E2E canary. It exercises the full checkpoint/hook lifecycle without
// real API calls.
package fakeagent

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(AgentNameFake, NewFakeAgent)
}

const (
	// AgentNameFake is the registry key for the fake agent.
	AgentNameFake types.AgentName = "fake"
	// AgentTypeFake is the type identifier stored in metadata.
	AgentTypeFake types.AgentType = "Fake Agent"
)

// FakeAgent implements agent.Agent and agent.HookSupport for E2E canary tests.
type FakeAgent struct{}

// NewFakeAgent creates a new fake agent instance.
func NewFakeAgent() agent.Agent { return &FakeAgent{} }

func (f *FakeAgent) Name() types.AgentName { return AgentNameFake }
func (f *FakeAgent) Type() types.AgentType { return AgentTypeFake }
func (f *FakeAgent) Description() string   { return "Fake Agent - deterministic E2E canary (no API calls)" }
func (f *FakeAgent) IsPreview() bool       { return false }
func (f *FakeAgent) ProtectedDirs() []string { return []string{".fakeagent"} }

// DetectPresence returns false — fake agent is never auto-detected.
func (f *FakeAgent) DetectPresence(_ context.Context) (bool, error) { return false, nil }

// --- Transcript Storage ---

func (f *FakeAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from hook input
	if err != nil {
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	return data, nil
}

func (f *FakeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	return agent.ChunkJSONL(content, maxSize)
}

func (f *FakeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

// --- Legacy Session Methods ---

func (f *FakeAgent) GetSessionID(input *agent.HookInput) string { return input.SessionID }

func (f *FakeAgent) GetSessionDir(repoPath string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_FAKE_PROJECT_DIR"); override != "" {
		return override, nil
	}
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("get home dir: %w", err)
	}
	return filepath.Join(homeDir, ".fakeagent", "sessions"), nil
}

func (f *FakeAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

func (f *FakeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}
	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // Path from hook input
	if err != nil {
		if os.IsNotExist(err) {
			// Transcript may not exist yet — return empty session
			return &agent.AgentSession{
				SessionID:  input.SessionID,
				AgentName:  f.Name(),
				SessionRef: input.SessionRef,
			}, nil
		}
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	return &agent.AgentSession{
		SessionID:  input.SessionID,
		AgentName:  f.Name(),
		SessionRef: input.SessionRef,
		NativeData: data,
	}, nil
}

func (f *FakeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}
	if session.SessionRef == "" {
		return errors.New("session reference is required")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
		return fmt.Errorf("create session dir: %w", err)
	}
	return os.WriteFile(session.SessionRef, session.NativeData, 0o600)
}

func (f *FakeAgent) FormatResumeCommand(sessionID string) string {
	return "fakeagent --session-id " + sessionID
}

