// Compile-time interface assertions.
var _ agent.HookSupport = (*FakeAgent)(nil)

const (
	HookNameSessionStart     = "session-start"
	HookNameSessionEnd       = "session-end"
	HookNameStop             = "stop"
	HookNameUserPromptSubmit = "user-prompt-submit"
)

// HookNames returns the hooks the fake agent supports.
func (f *FakeAgent) HookNames() []string {
	return []string{
		HookNameSessionStart,
		HookNameSessionEnd,
		HookNameStop,
		HookNameUserPromptSubmit,
	}
}

// ParseHookEvent translates fake agent hook JSON into a normalized lifecycle Event.
func (f *FakeAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.SessionStart,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Timestamp:  time.Now(),
		}, nil

	case HookNameUserPromptSubmit:
		raw, err := agent.ReadAndParseHookInput[userPromptSubmitRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.TurnStart,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Prompt:     raw.Prompt,
			Timestamp:  time.Now(),
		}, nil

	case HookNameStop:
		raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.TurnEnd,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Timestamp:  time.Now(),
		}, nil

	case HookNameSessionEnd:
		raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.SessionEnd,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Timestamp:  time.Now(),
		}, nil

	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// InstallHooks is a no-op — the fakeagent binary fires hooks directly.
func (f *FakeAgent) InstallHooks(_ context.Context, _ bool, _ bool) (int, error) {
	return 0, nil
}

// UninstallHooks is a no-op.
func (f *FakeAgent) UninstallHooks(_ context.Context) error { return nil }

// AreHooksInstalled returns true if the fakeagent binary is on PATH.
func (f *FakeAgent) AreHooksInstalled(_ context.Context) bool {
	_, err := os.Stat(fmt.Sprintf("/usr/local/bin/fakeagent"))
	// Just return true — fake agent hooks are built-in, not installed externally.
	_ = err
	return true
}

// WriteHookResponse writes a plain text message to stdout.
func (f *FakeAgent) WriteHookResponse(message string) error {
	_, err := fmt.Fprintln(os.Stdout, message)
	return err
}

// Hook JSON types — same format as other agents for consistency.

type sessionInfoRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
}

type userPromptSubmitRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Prompt         string `json:"prompt"`
}

