)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "fake" {
		return
	}
	// Only register if the binary exists (built by the test runner).
	if _, err := exec.LookPath("fakeagent"); err != nil {
		return
	}
	Register(&Fake{})
}

// Fake implements the Agent interface using a deterministic binary
// that creates files and fires hooks without making any API calls.
type Fake struct{}

func (f *Fake) Name() string               { return "fake" }
func (f *Fake) Binary() string             { return "fakeagent" }
func (f *Fake) EntireAgent() string        { return "fake" }
func (f *Fake) PromptPattern() string      { return `>` }
func (f *Fake) TimeoutMultiplier() float64 { return 0.5 } // Faster than real agents

func (f *Fake) Bootstrap() error { return nil }

func (f *Fake) IsTransientError(_ Output, _ error) bool { return false }

func (f *Fake) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	args := []string{"-p", prompt}
	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt)}

	cmd := exec.CommandContext(ctx, f.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	return Output{
		Command:  f.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (f *Fake) StartSession(_ context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("fake-test-%d", time.Now().UnixNano())
	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, f.Binary())
	if err != nil {
		return nil, err
	}

	// Wait for the interactive prompt.
	if _, err := s.WaitFor(`>`, 10*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

