25→// Fake implements the Agent interface using a deterministic binary
26→// that creates files and fires hooks without making any API calls.
27→type Fake struct{}
28→
29→func (f *Fake) Name() string               { return "fake" }
30→func (f *Fake) Binary() string             { return "fakeagent" }
31→func (f *Fake) EntireAgent() string        { return "fake" }
32→func (f *Fake) PromptPattern() string      { return `>` }
33→func (f *Fake) TimeoutMultiplier() float64 { return 0.5 } // Faster than real agents
34→
35→func (f *Fake) Bootstrap() error { return nil }
36→
37→func (f *Fake) IsTransientError(_ Output, _ error) bool { return false }
