39→func (f *Fake) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
40→	args := []string{"-p", prompt}
41→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt)}
42→
43→	cmd := exec.CommandContext(ctx, f.Binary(), args...)
44→	cmd.Dir = dir
45→	cmd.Stdin = nil
46→	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
47→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
48→	cmd.Cancel = func() error {
49→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
50→	}
51→	cmd.WaitDelay = 5 * time.Second
52→
53→	var stdout, stderr strings.Builder
54→	cmd.Stdout = &stdout
55→	cmd.Stderr = &stderr
56→
57→	err := cmd.Run()
58→	exitCode := 0
59→	if err != nil {
60→		exitErr := &exec.ExitError{}
61→		if errors.As(err, &exitErr) {
62→			exitCode = exitErr.ExitCode()
63→		} else {
64→			exitCode = -1
65→		}
66→	}
67→
68→	return Output{
69→		Command:  f.Binary() + " " + strings.Join(displayArgs, " "),
70→		Stdout:   stdout.String(),
71→		Stderr:   stderr.String(),
72→		ExitCode: exitCode,
73→	}, err
74→}
