76→func (f *Fake) StartSession(_ context.Context, dir string) (Session, error) {
77→	name := fmt.Sprintf("fake-test-%d", time.Now().UnixNano())
78→	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, f.Binary())
79→	if err != nil {
80→		return nil, err
81→	}
82→
83→	// Wait for the interactive prompt.
84→	if _, err := s.WaitFor(`>`, 10*time.Second); err != nil {
85→		_ = s.Close()
86→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
87→	}
88→	s.stableAtSend = ""
89→
90→	return s, nil
91→}
