117→func configureDroidRepoSettings(repoDir string) error {
118→	home, err := os.UserHomeDir()
119→	if err != nil {
120→		return fmt.Errorf("get home dir: %w", err)
121→	}
122→
123→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
124→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
125→
126→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
127→		return err
128→	}
129→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
130→		return fmt.Errorf("exclude droid settings from git: %w", err)
131→	}
132→	return nil
133→}
