135→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
136→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
137→	if err != nil {
138→		return err
139→	}
140→
141→	customModels, ok := globalSettings["customModels"]
142→	if !ok {
143→		return fmt.Errorf(
144→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
145→			globalSettingsPath,
146→			repoSettingsPath,
147→		)
148→	}
149→
150→	var models []json.RawMessage
151→	if err := json.Unmarshal(customModels, &models); err != nil {
152→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
153→	}
154→	if len(models) == 0 {
155→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
156→	}
157→
158→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
159→	if err != nil {
160→		return err
161→	}
162→	repoSettings["customModels"] = customModels
163→
164→	// Set the active custom model so interactive mode uses the BYOK model
165→	// instead of prompting for selection. The value must match the Model
166→	// field from the customModels entry (not the displayName).
167→	modelJSON, err := json.Marshal(agents.DefaultDroidModel())
168→	if err != nil {
169→		return fmt.Errorf("marshal model setting: %w", err)
170→	}
171→	repoSettings["model"] = json.RawMessage(modelJSON)
172→
173→	// High autonomy prevents Droid from asking for confirmation during
174→	// interactive E2E tests, which would cause hangs waiting for input.
175→	repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
176→	repoSettings["completionSound"] = json.RawMessage(`"off"`)
177→
178→	out, err := json.MarshalIndent(repoSettings, "", "  ")
179→	if err != nil {
180→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
181→	}
182→	out = append(out, '\n')
183→
184→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
185→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
186→	}
187→	return nil
188→}
