190→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
191→	data, err := os.ReadFile(path)
192→	if err != nil {
193→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
194→	}
195→
196→	var parsed map[string]json.RawMessage
197→	if err := json.Unmarshal(data, &parsed); err != nil {
198→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
199→	}
200→	if parsed == nil {
201→		parsed = make(map[string]json.RawMessage)
202→	}
203→	return parsed, nil
204→}
