240→// ForEachAgent runs fn as a parallel subtest for every registered agent.
241→// It handles repo setup, concurrency gating, context timeout, and cleanup.
242→// The timeout is scaled by each agent's TimeoutMultiplier.
243→//
244→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
245→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
246→// panic and restarts the entire scenario with a fresh repository, up to
247→// maxScenarioRestarts times. This avoids stale CLI session state from the
248→// failed attempt poisoning the retry.
249→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
250→	t.Helper()
251→	t.Parallel()
252→	all := agents.All()
253→	if len(all) == 0 {
254→		t.Skip("no agents registered (check E2E_AGENT filter)")
255→	}
256→	for _, agent := range all {
257→		t.Run(agent.Name(), func(t *testing.T) {
258→			// Use the global test deadline for slot wait so we don't
259→			// skip prematurely — only bail if the whole binary is dying.
260→			slotCtx := context.Background()
261→			if deadline, ok := t.Deadline(); ok {
262→				var cancel context.CancelFunc
263→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
264→				defer cancel()
265→			}
266→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
267→				t.Fatalf("timed out waiting for agent slot: %v", err)
268→			}
269→			defer agents.ReleaseSlot(agent)
270→
271→			// Per-test timeout starts after slot is acquired, scaled
272→			// by the agent's multiplier (e.g. 2.5× for gemini).
273→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
274→
275→			var prevState *RepoState
276→			for attempt := range maxScenarioRestarts + 1 {
277→				s := SetupRepo(t, agent)
278→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
279→
280→				// On restart, suppress artifact capture from the previous
281→				// failed attempt so it doesn't overwrite the final one.
282→				if prevState != nil {
283→					prevState.skipArtifacts = true
284→				}
285→
286→				restarted := runScenario(t, s, ctx, fn)
287→				cancel()
288→
289→				if !restarted {
290→					return
291→				}
292→				prevState = s
293→				if attempt >= maxScenarioRestarts {
294→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
295→				}
296→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
297→			}
298→		})
299→	}
300→}
301→
302→// runScenario runs the test function and recovers from errScenarioRestart
303→// panics triggered by transient API errors in RunPrompt. Returns true if
304→// the scenario should be restarted with a fresh repository.
305→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
306→	t.Helper()
307→	defer func() {
308→		if r := recover(); r != nil {
309→			if _, ok := r.(errScenarioRestart); ok {
310→				restarted = true
311→				return
312→			}
313→			panic(r) // re-panic for unexpected panics
314→		}
315→	}()
316→	fn(t, s, ctx)
317→	return false
318→}
319→
320→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
321→
322→// errScenarioRestart is panicked by RunPrompt when a transient API error is
323→// detected. ForEachAgent recovers from this panic and restarts the test
324→// scenario with a fresh repository, avoiding stale CLI state from the failed
325→// attempt.
326→type errScenarioRestart struct {
327→	msg string
328→}
329→
330→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
331→// and returns the result. If the agent reports a transient API error, it
332→// panics with errScenarioRestart to trigger a full scenario restart in
333→// ForEachAgent (see runScenario).
334→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
335→	t.Helper()
336→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
337→	s.logPromptResult(out)
338→
339→	if err != nil && s.Agent.IsTransientError(out, err) {
340→		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
341→		t.Logf("%s — restarting scenario", errMsg)
342→		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
343→		panic(errScenarioRestart{msg: errMsg})
344→	}
345→
346→	return out, err
347→}
348→
349→func (s *RepoState) logPromptResult(out agents.Output) {
350→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
351→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
352→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
