  1→// fakeagent is a deterministic agent binary for E2E canary tests.
  2→// It parses simple prompt instructions, performs file operations, fires
  3→// lifecycle hooks via `entire hooks fake <verb>`, and writes a minimal
  4→// JSONL transcript. No API calls are made.
  5→//
  6→// Usage:
  7→//
  8→//	fakeagent -p <prompt>   # Headless (single-turn) mode
  9→//	fakeagent               # Interactive (multi-turn) mode
 10→package main
 11→
 12→import (
 13→	"bufio"
 14→	"bytes"
 15→	"encoding/json"
 16→	"fmt"
 17→	"os"
 18→	"os/exec"
 19→	"path/filepath"
 20→	"regexp"
 21→	"strings"
 22→	"time"
 23→
 24→	"github.com/google/uuid"
 25→)
 26→
 27→func main() {
 28→	prompt := ""
 29→	for i := 1; i < len(os.Args); i++ {
 30→		if os.Args[i] == "-p" && i+1 < len(os.Args) {
 31→			prompt = os.Args[i+1]
 32→			i++
 33→		}
 34→	}
 35→
 36→	dir, err := os.Getwd() //nolint:forbidigo // Standalone binary, not part of CLI — CWD is the repo dir
 37→	if err != nil {
 38→		fatal("getwd: %v", err)
 39→	}
 40→
 41→	sessionID := uuid.New().String()
 42→	transcriptPath := setupTranscript(dir, sessionID)
 43→
 44→	fireHook(dir, "session-start", map[string]string{
 45→		"session_id":      sessionID,
 46→		"transcript_path": transcriptPath,
 47→	})
 48→
 49→	if prompt != "" {
 50→		// Headless mode: single prompt
 51→		runTurn(dir, sessionID, transcriptPath, prompt)
 52→	} else {
 53→		// Interactive mode: read prompts from stdin
 54→		fmt.Fprint(os.Stdout, "> ")
 55→		scanner := bufio.NewScanner(os.Stdin)
 56→		for scanner.Scan() {
 57→			line := strings.TrimSpace(scanner.Text())
 58→			if line == "" || line == "exit" || line == "quit" {
 59→				break
 60→			}
 61→			// Give tmux's Send() time to capture the echoed-input state
 62→			// before we produce any output. Send polls every 200ms; without
 63→			// this pause, fakeagent output appears in the same capture window
 64→			// as the echo, causing stableAtSend to include final output and
 65→			// preventing WaitFor's contentChanged detection.
 66→			time.Sleep(700 * time.Millisecond)
 67→			fmt.Fprintln(os.Stdout, "Working...")
 68→			runTurn(dir, sessionID, transcriptPath, line)
 69→			fmt.Fprint(os.Stdout, "> ")
 70→		}
 71→	}
 72→
 73→	fireHook(dir, "session-end", map[string]string{
 74→		"session_id":      sessionID,
 75→		"transcript_path": transcriptPath,
 76→	})
 77→}
 78→
 79→func runTurn(dir, sessionID, transcriptPath, prompt string) {
 80→	fireHook(dir, "user-prompt-submit", map[string]any{
 81→		"session_id":      sessionID,
 82→		"transcript_path": transcriptPath,
 83→		"prompt":          prompt,
 84→	})
 85→
 86→	appendTranscript(transcriptPath, "user", prompt)
 87→
 88→	actions := parsePrompt(prompt)
 89→	executeActions(dir, actions)
 90→
 91→	appendTranscript(transcriptPath, "assistant", fmt.Sprintf("Done. Executed %d actions.", len(actions)))
 92→	fmt.Fprintf(os.Stdout, "Done. Executed %d actions.\n", len(actions))
 93→
 94→	fireHook(dir, "stop", map[string]string{
 95→		"session_id":      sessionID,
 96→		"transcript_path": transcriptPath,
 97→	})
 98→}
 99→
100→// --- Prompt Parsing ---
101→
102→type action struct {
103→	kind    string // "create", "modify", "delete", "commit"
104→	path    string
105→	content string
106→}
107→
108→var (
109→	// "create a [single|new|...] [markdown|text] file [at|called] <path>"
110→	createFileRe = regexp.MustCompile(`(?i)create\s+(?:a\s+)?(?:\w+\s+)*?(?:markdown\s+|text\s+)?file\s+(?:at\s+|called\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
111→	// "create N files: <path> about <topic>, <path> about <topic>"
112→	createMultiRe = regexp.MustCompile(`(?i)create\s+(?:\w+\s+)*?(?:four|three|two|\d+)\s+(?:\w+\s+)*?(?:markdown\s+)?files?:?\s+(.+)`)
113→	// "modify <path>"
114→	modifyFileRe = regexp.MustCompile(`(?i)modify\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
115→	// "modify [these] N [existing] files[:]"
116→	modifyMultiRe = regexp.MustCompile(`(?i)modify\s+(?:these\s+)?(?:three|four|two|\d+)\s+(?:\w+\s+)*?files?[.:]\s*(.+)`)
117→	// "add ... to <path>" (e.g. "add another stanza to poem.txt")
118→	addToFileRe = regexp.MustCompile(`(?i)add\s+(?:another\s+|a\s+|some\s+)?\w+\s+to\s+([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
119→	// "delete <path>"
120→	deleteFileRe = regexp.MustCompile(`(?i)delete\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
121→	// "commit" anywhere in the prompt, but not "do not commit" / "don't commit"
122→	commitRe = regexp.MustCompile(`(?i)(?:then\s+|now\s+)?(?:git\s+)?commit\b`)
123→	// Negative: "do not commit" / "don't commit" with optional object, at sentence boundary
124→	// Matches: "Do not commit.", "Do not commit the file.", "Do not commit them,"
125→	// Does NOT match: "Do not commit any other files" (different intent)
126→	noCommitRe = regexp.MustCompile(`(?i)(?:do\s+not|don'?t)\s+commit(?:\s+(?:it|them|the\s+\w+))?(?:\.|,|$)`)
127→	// "commit each file separately" — interleave create+commit
128→	commitSeparatelyRe = regexp.MustCompile(`(?i)commit\s+each\s+file\s+separately`)
129→	// Individual file in multi-create: "docs/a.md about apples"
130→	// Topic capture stops at comma, "and", period followed by space+uppercase, or end
131→	multiFileItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+(?:about\s+|with\s+|containing\s+)?(.+?)(?:,\s*|\s+and\s+|\.\s+[A-Z]|\.\s*$)`)
132→	// Individual file in multi-modify: "src/model.go should define ..."
133→	modifyItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+should\s+(.+?)(?:,|$)`)
134→	// "In src/a.go, add ..." pattern for multi-modify
135→	inFileRe = regexp.MustCompile(`[Ii]n\s+([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
136→	// Inline content: "with content 'package main; func Foo() {}'"
137→	inlineContentRe = regexp.MustCompile(`(?i)with\s+content\s+['"]([^'"]+)['"]`)
138→)
139→
140→func parsePrompt(prompt string) []action {
141→	var actions []action
142→
143→	// Multi-file modify: "modify these three files: src/model.go should ..., src/view.go should ..."
144→	// Also matches: "Modify two existing files. In src/a.go, add ..."
145→	if m := modifyMultiRe.FindStringSubmatch(prompt); m != nil {
146→		// Try "should" pattern first
147→		items := modifyItemRe.FindAllStringSubmatch(m[1], -1)
148→		for _, item := range items {
149→			actions = append(actions, action{
150→				kind:    "modify",
151→				path:    item[1],
152→				content: "// " + strings.TrimSpace(item[2]) + "\n",
153→			})
154→		}
155→		// Try "In <path>" pattern as fallback
156→		if len(actions) == 0 {
157→			for _, item := range inFileRe.FindAllStringSubmatch(m[1], -1) {
158→				actions = append(actions, action{
159→					kind:    "modify",
160→					path:    item[1],
161→					content: "// Modified by fake agent\n",
162→				})
163→			}
164→		}
165→		// Last resort: extract any file paths
166→		if len(actions) == 0 {
167→			fileRe := regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
168→			for _, fm := range fileRe.FindAllStringSubmatch(m[1], -1) {
169→				actions = append(actions, action{
170→					kind:    "modify",
171→					path:    fm[1],
172→					content: "// Modified by fake agent\n",
173→				})
174→			}
175→		}
176→	}
177→
178→	// Multi-file create: "create four markdown files: docs/a.md about apples, ..."
179→	if len(actions) == 0 || hasModifyOnly(actions) {
180→		if m := createMultiRe.FindStringSubmatch(prompt); m != nil {
181→			items := multiFileItemRe.FindAllStringSubmatch(m[1], -1)
182→			for _, item := range items {
183→				actions = append(actions, action{
184→					kind:    "create",
185→					path:    item[1],
186→					content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", strings.TrimSpace(item[2]), strings.TrimSpace(item[2])),
187→				})
188→			}
189→		}
190→	}
191→
192→	// Single file create — also runs if we only have modifies (combined prompts)
193→	if !hasCreate(actions) {
194→		if m := createFileRe.FindStringSubmatch(prompt); m != nil {
195→			content := fmt.Sprintf("# %s\n\nA paragraph about %s.\n", extractTopic(prompt), extractTopic(prompt))
196→			if ic := inlineContentRe.FindStringSubmatch(prompt); ic != nil {
197→				content = ic[1] + "\n"
198→			}
199→			actions = append(actions, action{
200→				kind:    "create",
201→				path:    m[1],
202→				content: content,
203→			})
204→		}
205→	}
206→
207→	// Single file modify — also runs if we only have creates (combined prompts)
208→	if !hasModify(actions) {
209→		if m := modifyFileRe.FindStringSubmatch(prompt); m != nil {
210→			actions = append(actions, action{
211→				kind:    "modify",
212→				path:    m[1],
213→				content: "// Modified by fake agent\n",
214→			})
215→		}
216→	}
217→
218→	// "add ... to <path>" as modify (e.g. "add another stanza to poem.txt")
219→	if !hasModify(actions) {
220→		if m := addToFileRe.FindStringSubmatch(prompt); m != nil {
221→			actions = append(actions, action{
222→				kind:    "modify",
223→				path:    m[1],
224→				content: "// Modified by fake agent\n",
225→			})
226→		}
227→	}
228→
229→	// Delete
230→	if m := deleteFileRe.FindStringSubmatch(prompt); m != nil {
231→		actions = append(actions, action{kind: "delete", path: m[1]})
232→	}
233→
234→	// Commit: check for "commit each file separately" (interleaved) vs normal.
235→	// Skip if prompt contains "do not commit" / "don't commit".
236→	if !noCommitRe.MatchString(prompt) {
237→		if commitSeparatelyRe.MatchString(prompt) {
238→			actions = interleaveCommits(actions)
239→		} else if commitRe.MatchString(prompt) {
240→			actions = append(actions, action{kind: "commit"})
241→		}
242→	}
243→
244→	return actions
245→}
246→
247→func hasCreate(actions []action) bool {
248→	for _, a := range actions {
249→		if a.kind == "create" {
250→			return true
251→		}
252→	}
253→	return false
254→}
255→
256→func hasModify(actions []action) bool {
257→	for _, a := range actions {
258→		if a.kind == "modify" {
259→			return true
260→		}
261→	}
262→	return false
263→}
264→
265→func hasModifyOnly(actions []action) bool {
266→	if len(actions) == 0 {
267→		return false
268→	}
269→	for _, a := range actions {
270→		if a.kind != "modify" {
271→			return false
272→		}
273→	}
274→	return true
275→}
276→
277→// interleaveCommits inserts a commit after each create/modify action.
278→func interleaveCommits(actions []action) []action {
279→	var result []action
280→	for _, a := range actions {
281→		result = append(result, a)
282→		if a.kind == "create" || a.kind == "modify" {
283→			result = append(result, action{kind: "commit"})
284→		}
285→	}
286→	return result
287→}
288→
289→func extractTopic(prompt string) string {
290→	// "about the colour red" → "the colour red"
291→	re := regexp.MustCompile(`(?i)about\s+(.+?)(?:\.|,|\s+Do\s|\s+do\s|\s+then\s|$)`)
292→	if m := re.FindStringSubmatch(prompt); m != nil {
293→		return strings.TrimSpace(m[1])
294→	}
295→	return "the topic"
296→}
297→
298→func executeActions(dir string, actions []action) {
299→	for _, a := range actions {
300→		switch a.kind {
301→		case "create":
302→			createFile(dir, a.path, a.content)
303→		case "modify":
304→			modifyFile(dir, a.path, a.content)
305→		case "delete":
306→			deleteFile(dir, a.path)
307→		case "commit":
308→			gitCommit(dir)
309→		}
310→	}
311→}
312→
313→func createFile(dir, path, content string) {
314→	abs := filepath.Join(dir, path)
315→	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
316→		fmt.Fprintf(os.Stderr, "mkdir %s: %v\n", filepath.Dir(abs), err)
317→		return
318→	}
319→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
320→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
321→	}
322→}
323→
324→func modifyFile(dir, path, appendContent string) {
325→	abs := filepath.Join(dir, path)
326→	existing, _ := os.ReadFile(abs)
327→	content := string(existing) + "\n" + appendContent
328→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
329→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
330→	}
331→}
332→
333→func deleteFile(dir, path string) {
334→	abs := filepath.Join(dir, path)
335→	if err := os.Remove(abs); err != nil {
336→		fmt.Fprintf(os.Stderr, "remove %s: %v\n", abs, err)
337→	}
338→}
339→
340→func gitCommit(dir string) {
341→	gitRun(dir, "add", ".")
342→	gitRun(dir, "commit", "-m", "Fake agent commit")
343→}
344→
345→func gitRun(dir string, args ...string) {
346→	cmd := exec.Command("git", args...)
347→	cmd.Dir = dir
348→	cmd.Stdout = os.Stdout
349→	cmd.Stderr = os.Stderr
350→	// Signal that this is a non-interactive agent — git hooks should not
351→	// attempt TTY prompts. GIT_TERMINAL_PROMPT is the standard git env var
352→	// for this (same approach used by Factory AI Droid).
353→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
354→	if err := cmd.Run(); err != nil {
355→		fmt.Fprintf(os.Stderr, "git %s: %v\n", strings.Join(args, " "), err)
356→	}
357→}
358→
359→// --- Hook Firing ---
360→
361→func fireHook(dir, hookName string, payload any) {
362→	data, err := json.Marshal(payload)
363→	if err != nil {
364→		fmt.Fprintf(os.Stderr, "marshal hook payload: %v\n", err)
365→		return
