// Package vogon implements the Agent interface for a deterministic test agent
// used as an E2E canary. It exercises the full checkpoint/hook lifecycle without
// real API calls. Named after the Vogons from The Hitchhiker's Guide to the
// Galaxy — bureaucratic, procedural, and deterministic to a fault.
package vogon

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(AgentNameVogon, NewVogonAgent)
}

const (
	// AgentNameVogon is the registry key for the vogon agent.
	AgentNameVogon types.AgentName = "vogon"
	// AgentTypeVogon is the type identifier stored in metadata.
	AgentTypeVogon types.AgentType = "Vogon Agent"
)

// VogonAgent implements agent.Agent and agent.HookSupport for E2E canary tests.
type VogonAgent struct{}

// NewVogonAgent creates a new vogon agent instance.
func NewVogonAgent() agent.Agent { return &VogonAgent{} }

func (v *VogonAgent) Name() types.AgentName { return AgentNameVogon }
func (v *VogonAgent) Type() types.AgentType { return AgentTypeVogon }
func (v *VogonAgent) Description() string {
	return "Vogon Agent - deterministic E2E canary (no API calls)"
}
func (v *VogonAgent) IsPreview() bool         { return false }
func (v *VogonAgent) ProtectedDirs() []string { return []string{".vogon"} }

// DetectPresence returns false — vogon agent is never auto-detected.
func (v *VogonAgent) DetectPresence(_ context.Context) (bool, error) { return false, nil }

// --- Transcript Storage ---

func (v *VogonAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from hook input
	if err != nil {
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	return data, nil
}

func (v *VogonAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("chunk transcript: %w", err)
	}
	return chunks, nil
}

func (v *VogonAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

// --- Legacy Session Methods ---

func (v *VogonAgent) GetSessionID(input *agent.HookInput) string { return input.SessionID }

func (v *VogonAgent) GetSessionDir(_ string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_VOGON_PROJECT_DIR"); override != "" {
		return override, nil
	}
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("get home dir: %w", err)
	}
	return filepath.Join(homeDir, ".vogon", "sessions"), nil
}

func (v *VogonAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

func (v *VogonAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}
	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		if os.IsNotExist(err) {
			// Transcript may not exist yet — return empty session
			return &agent.AgentSession{
				SessionID:  input.SessionID,
				AgentName:  v.Name(),
				SessionRef: input.SessionRef,
			}, nil
		}
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	return &agent.AgentSession{
		SessionID:  input.SessionID,
		AgentName:  v.Name(),
		SessionRef: input.SessionRef,
		NativeData: data,
	}, nil
}

func (v *VogonAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}
	if session.SessionRef == "" {
		return errors.New("session reference is required")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
		return fmt.Errorf("create session dir: %w", err)
	}
	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("write session: %w", err)
	}
	return nil
}

func (v *VogonAgent) FormatResumeCommand(sessionID string) string {
	return "vogon --session-id " + sessionID
}

package vogon

import (
	"context"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time interface assertions.
var (
	_ agent.HookSupport        = (*VogonAgent)(nil)
	_ agent.HookResponseWriter = (*VogonAgent)(nil)
)

const (
	HookNameSessionStart     = "session-start"
	HookNameSessionEnd       = "session-end"
	HookNameStop             = "stop"
	HookNameUserPromptSubmit = "user-prompt-submit"
)

// HookNames returns the hooks the vogon agent supports.
func (v *VogonAgent) HookNames() []string {
	return []string{
		HookNameSessionStart,
		HookNameSessionEnd,
		HookNameStop,
		HookNameUserPromptSubmit,
	}
}

// ParseHookEvent translates vogon agent hook JSON into a normalized lifecycle Event.
func (v *VogonAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.SessionStart,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Timestamp:  time.Now(),
		}, nil

	case HookNameUserPromptSubmit:
		raw, err := agent.ReadAndParseHookInput[userPromptSubmitRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.TurnStart,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Prompt:     raw.Prompt,
			Timestamp:  time.Now(),
		}, nil

	case HookNameStop:
		raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.TurnEnd,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Timestamp:  time.Now(),
		}, nil

	case HookNameSessionEnd:
		raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
		if err != nil {
			return nil, err
		}
		return &agent.Event{
			Type:       agent.SessionEnd,
			SessionID:  raw.SessionID,
			SessionRef: raw.TranscriptPath,
			Timestamp:  time.Now(),
		}, nil

	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// InstallHooks is a no-op — the vogon binary fires hooks directly.
func (v *VogonAgent) InstallHooks(_ context.Context, _ bool, _ bool) (int, error) {
	return 0, nil
}

// UninstallHooks is a no-op.
func (v *VogonAgent) UninstallHooks(_ context.Context) error { return nil }

// AreHooksInstalled returns false — vogon agent has no external hooks to install.
// The vogon binary fires hooks directly via `entire hooks vogon <verb>`.
func (v *VogonAgent) AreHooksInstalled(_ context.Context) bool {
	return false
}

// WriteHookResponse writes a plain text message to stdout.
func (v *VogonAgent) WriteHookResponse(message string) error {
	if _, err := fmt.Fprintln(os.Stdout, message); err != nil {
		return fmt.Errorf("write hook response: %w", err)
	}
	return nil
}

// Hook JSON types — same format as other agents for consistency.

type sessionInfoRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
}

type userPromptSubmitRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Prompt         string `json:"prompt"`
}

package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "vogon" {
		return
	}
	// Only register if the binary exists (built by the test runner).
	if _, err := exec.LookPath("vogon"); err != nil {
		return
	}
	Register(&Vogon{})
}

// Vogon implements the Agent interface using a deterministic binary
// that creates files and fires hooks without making any API calls.
// Named after the Vogons from The Hitchhiker's Guide to the Galaxy.
type Vogon struct{}

func (v *Vogon) Name() string               { return "vogon" }
func (v *Vogon) Binary() string             { return "vogon" }
func (v *Vogon) EntireAgent() string        { return "vogon" }
func (v *Vogon) PromptPattern() string      { return `>` }
func (v *Vogon) TimeoutMultiplier() float64 { return 0.5 } // Faster than real agents

func (v *Vogon) Bootstrap() error { return nil }

func (v *Vogon) IsTransientError(_ Output, _ error) bool { return false }

func (v *Vogon) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	args := []string{"-p", prompt}
	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt)}

	cmd := exec.CommandContext(ctx, v.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	return Output{
		Command:  v.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (v *Vogon) StartSession(_ context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("vogon-test-%d", time.Now().UnixNano())
	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, v.Binary())
	if err != nil {
		return nil, err
	}

	// Wait for the interactive prompt.
	if _, err := s.WaitFor(`>`, 10*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

