 27→func main() {
 28→	prompt := ""
 29→	for i := 1; i < len(os.Args); i++ {
 30→		if os.Args[i] == "-p" && i+1 < len(os.Args) {
 31→			prompt = os.Args[i+1]
 32→			i++
 33→		}
 34→	}
 35→
 36→	dir, err := os.Getwd() //nolint:forbidigo // Standalone binary, not part of CLI — CWD is the repo dir
 37→	if err != nil {
 38→		fatal("getwd: %v", err)
 39→	}
 40→
 41→	sessionID := uuid.New().String()
 42→	transcriptPath := setupTranscript(dir, sessionID)
 43→
 44→	fireHook(dir, "session-start", map[string]string{
 45→		"session_id":      sessionID,
 46→		"transcript_path": transcriptPath,
 47→	})
 48→
 49→	if prompt != "" {
 50→		// Headless mode: single prompt
 51→		runTurn(dir, sessionID, transcriptPath, prompt)
 52→	} else {
 53→		// Interactive mode: read prompts from stdin
 54→		fmt.Fprint(os.Stdout, "> ")
 55→		scanner := bufio.NewScanner(os.Stdin)
 56→		for scanner.Scan() {
 57→			line := strings.TrimSpace(scanner.Text())
 58→			if line == "" || line == "exit" || line == "quit" {
 59→				break
 60→			}
 61→			// Give tmux's Send() time to capture the echoed-input state
 62→			// before we produce any output. Send polls every 200ms; without
 63→			// this pause, fakeagent output appears in the same capture window
 64→			// as the echo, causing stableAtSend to include final output and
 65→			// preventing WaitFor's contentChanged detection.
 66→			time.Sleep(700 * time.Millisecond)
 67→			fmt.Fprintln(os.Stdout, "Working...")
 68→			runTurn(dir, sessionID, transcriptPath, line)
 69→			fmt.Fprint(os.Stdout, "> ")
 70→		}
 71→	}
 72→
 73→	fireHook(dir, "session-end", map[string]string{
 74→		"session_id":      sessionID,
 75→		"transcript_path": transcriptPath,
 76→	})
 77→}
 78→
 79→func runTurn(dir, sessionID, transcriptPath, prompt string) {
 80→	fireHook(dir, "user-prompt-submit", map[string]any{
 81→		"session_id":      sessionID,
 82→		"transcript_path": transcriptPath,
 83→		"prompt":          prompt,
 84→	})
 85→
 86→	appendTranscript(transcriptPath, "user", prompt)
 87→
 88→	actions := parsePrompt(prompt)
 89→	executeActions(dir, actions)
 90→
 91→	appendTranscript(transcriptPath, "assistant", fmt.Sprintf("Done. Executed %d actions.", len(actions)))
 92→	fmt.Fprintf(os.Stdout, "Done. Executed %d actions.\n", len(actions))
 93→
 94→	fireHook(dir, "stop", map[string]string{
 95→		"session_id":      sessionID,
 96→		"transcript_path": transcriptPath,
 97→	})
 98→}
 99→
100→// --- Prompt Parsing ---
101→
102→type action struct {
103→	kind    string // "create", "modify", "delete", "commit"
104→	path    string
105→	content string
106→}
107→
108→var (
109→	// "create a [single|new|...] [markdown|text] file [at|called] <path>"
110→	createFileRe = regexp.MustCompile(`(?i)create\s+(?:a\s+)?(?:\w+\s+)*?(?:markdown\s+|text\s+)?file\s+(?:at\s+|called\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
111→	// "create N files: <path> about <topic>, <path> about <topic>"
112→	createMultiRe = regexp.MustCompile(`(?i)create\s+(?:\w+\s+)*?(?:four|three|two|\d+)\s+(?:\w+\s+)*?(?:markdown\s+)?files?:?\s+(.+)`)
113→	// "modify <path>"
114→	modifyFileRe = regexp.MustCompile(`(?i)modify\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
115→	// "modify [these] N [existing] files[:]"
116→	modifyMultiRe = regexp.MustCompile(`(?i)modify\s+(?:these\s+)?(?:three|four|two|\d+)\s+(?:\w+\s+)*?files?[.:]\s*(.+)`)
117→	// "add ... to <path>" (e.g. "add another stanza to poem.txt")
118→	addToFileRe = regexp.MustCompile(`(?i)add\s+(?:another\s+|a\s+|some\s+)?\w+\s+to\s+([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
119→	// "delete <path>"
120→	deleteFileRe = regexp.MustCompile(`(?i)delete\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
121→	// "commit" anywhere in the prompt, but not "do not commit" / "don't commit"
122→	commitRe = regexp.MustCompile(`(?i)(?:then\s+|now\s+)?(?:git\s+)?commit\b`)
123→	// Negative: "do not commit" / "don't commit" with optional object, at sentence boundary
124→	// Matches: "Do not commit.", "Do not commit the file.", "Do not commit them,"
125→	// Does NOT match: "Do not commit any other files" (different intent)
126→	noCommitRe = regexp.MustCompile(`(?i)(?:do\s+not|don'?t)\s+commit(?:\s+(?:it|them|the\s+\w+))?(?:\.|,|$)`)
127→	// "commit each file separately" — interleave create+commit
128→	commitSeparatelyRe = regexp.MustCompile(`(?i)commit\s+each\s+file\s+separately`)
129→	// Individual file in multi-create: "docs/a.md about apples"
130→	// Topic capture stops at comma, "and", period followed by space+uppercase, or end
131→	multiFileItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+(?:about\s+|with\s+|containing\s+)?(.+?)(?:,\s*|\s+and\s+|\.\s+[A-Z]|\.\s*$)`)
132→	// Individual file in multi-modify: "src/model.go should define ..."
133→	modifyItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+should\s+(.+?)(?:,|$)`)
134→	// "In src/a.go, add ..." pattern for multi-modify
135→	inFileRe = regexp.MustCompile(`[Ii]n\s+([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
136→	// Inline content: "with content 'package main; func Foo() {}'"
137→	inlineContentRe = regexp.MustCompile(`(?i)with\s+content\s+['"]([^'"]+)['"]`)
138→	// Numbered steps: "(1) ... (2) ... (3) ..."
139→	numberedStepRe = regexp.MustCompile(`\(\d+\)\s+`)
140→	// Explicit git command: "Run: git add ... && git commit -m '...'"
141→	explicitGitRe = regexp.MustCompile(`(?i)run:?\s+git\s+add\s+.+(?:&&\s*git\s+commit|;\s*git\s+commit)`)
142→)
143→
144→func parsePrompt(prompt string) []action {
145→	// Check for numbered-step prompts — parse each step independently to
146→	// preserve ordering (e.g., create, commit, then create more).
147→	if numberedStepRe.MatchString(prompt) {
148→		return parseNumberedSteps(prompt)
149→	}
150→	var actions []action
151→
152→	// Multi-file modify: "modify these three files: src/model.go should ..., src/view.go should ..."
153→	// Also matches: "Modify two existing files. In src/a.go, add ..."
154→	if m := modifyMultiRe.FindStringSubmatch(prompt); m != nil {
155→		// Try "should" pattern first
156→		items := modifyItemRe.FindAllStringSubmatch(m[1], -1)
157→		for _, item := range items {
158→			actions = append(actions, action{
159→				kind:    "modify",
160→				path:    item[1],
161→				content: "// " + strings.TrimSpace(item[2]) + "\n",
162→			})
163→		}
164→		// Try "In <path>" pattern as fallback
165→		if len(actions) == 0 {
166→			for _, item := range inFileRe.FindAllStringSubmatch(m[1], -1) {
167→				actions = append(actions, action{
168→					kind:    "modify",
169→					path:    item[1],
170→					content: "// Modified by fake agent\n",
171→				})
172→			}
173→		}
174→		// Last resort: extract any file paths
175→		if len(actions) == 0 {
176→			fileRe := regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
177→			for _, fm := range fileRe.FindAllStringSubmatch(m[1], -1) {
178→				actions = append(actions, action{
179→					kind:    "modify",
180→					path:    fm[1],
181→					content: "// Modified by fake agent\n",
182→				})
183→			}
184→		}
185→	}
186→
187→	// Multi-file create: "create four markdown files: docs/a.md about apples, ..."
188→	if len(actions) == 0 || hasModifyOnly(actions) {
189→		if m := createMultiRe.FindStringSubmatch(prompt); m != nil {
190→			items := multiFileItemRe.FindAllStringSubmatch(m[1], -1)
191→			for _, item := range items {
192→				actions = append(actions, action{
193→					kind:    "create",
194→					path:    item[1],
195→					content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", strings.TrimSpace(item[2]), strings.TrimSpace(item[2])),
196→				})
197→			}
198→		}
199→	}
200→
201→	// Single file create — also runs if we only have modifies (combined prompts)
202→	if !hasCreate(actions) {
203→		if m := createFileRe.FindStringSubmatch(prompt); m != nil {
204→			content := fmt.Sprintf("# %s\n\nA paragraph about %s.\n", extractTopic(prompt), extractTopic(prompt))
205→			if ic := inlineContentRe.FindStringSubmatch(prompt); ic != nil {
206→				content = ic[1] + "\n"
207→			}
208→			actions = append(actions, action{
209→				kind:    "create",
210→				path:    m[1],
211→				content: content,
212→			})
213→		}
214→	}
215→
216→	// Single file modify — also runs if we only have creates (combined prompts)
217→	if !hasModify(actions) {
218→		if m := modifyFileRe.FindStringSubmatch(prompt); m != nil {
219→			actions = append(actions, action{
220→				kind:    "modify",
221→				path:    m[1],
222→				content: "// Modified by fake agent\n",
223→			})
224→		}
225→	}
226→
227→	// "add ... to <path>" as modify (e.g. "add another stanza to poem.txt")
228→	if !hasModify(actions) {
229→		if m := addToFileRe.FindStringSubmatch(prompt); m != nil {
230→			actions = append(actions, action{
231→				kind:    "modify",
232→				path:    m[1],
233→				content: "// Modified by fake agent\n",
234→			})
235→		}
236→	}
237→
238→	// Delete
239→	if m := deleteFileRe.FindStringSubmatch(prompt); m != nil {
240→		actions = append(actions, action{kind: "delete", path: m[1]})
241→	}
242→
243→	// Commit: check for "commit each file separately" (interleaved) vs normal.
244→	// Skip if prompt contains "do not commit" / "don't commit".
245→	if !noCommitRe.MatchString(prompt) {
246→		if commitSeparatelyRe.MatchString(prompt) {
247→			actions = interleaveCommits(actions)
248→		} else if commitRe.MatchString(prompt) {
249→			actions = append(actions, action{kind: "commit"})
250→		}
251→	}
252→
253→	return actions
254→}
255→
256→// parseNumberedSteps splits "(1) ... (2) ... (3) ..." prompts into individual
257→// steps and parses each one, preserving ordering. This handles prompts like:
258→// "(1) Create file A. (2) Create file B. (3) git commit. (4) Create file C."
259→func parseNumberedSteps(prompt string) []action {
260→	// Split on numbered markers: "(1) ", "(2) ", etc.
261→	indices := numberedStepRe.FindAllStringIndex(prompt, -1)
262→	if len(indices) == 0 {
263→		return nil
264→	}
265→
266→	var steps []string
267→	for i, idx := range indices {
268→		start := idx[1] // after the "(N) " marker
269→		var end int
270→		if i+1 < len(indices) {
271→			end = indices[i+1][0]
272→		} else {
273→			end = len(prompt)
274→		}
275→		step := strings.TrimSpace(prompt[start:end])
276→		if step != "" {
277→			steps = append(steps, step)
278→		}
279→	}
280→
281→	var actions []action
282→	for _, step := range steps {
283→		// Explicit git command: "Run: git add ... && git commit ..."
284→		if explicitGitRe.MatchString(step) {
285→			actions = append(actions, action{kind: "commit"})
286→			continue
287→		}
288→
289→		// Create file with optional inline content
290→		if m := createFileRe.FindStringSubmatch(step); m != nil {
291→			content := fmt.Sprintf("# %s\n\nGenerated content.\n", m[1])
292→			if ic := inlineContentRe.FindStringSubmatch(step); ic != nil {
293→				content = ic[1] + "\n"
294→			}
295→			actions = append(actions, action{kind: "create", path: m[1], content: content})
296→			continue
297→		}
298→
299→		// Modify file
300→		if m := modifyFileRe.FindStringSubmatch(step); m != nil {
301→			actions = append(actions, action{kind: "modify", path: m[1], content: "// Modified by fake agent\n"})
302→			continue
303→		}
304→
305→		// Delete file
306→		if m := deleteFileRe.FindStringSubmatch(step); m != nil {
307→			actions = append(actions, action{kind: "delete", path: m[1]})
308→			continue
309→		}
310→
311→		// Bare commit instruction
312→		if commitRe.MatchString(step) && !noCommitRe.MatchString(step) {
313→			actions = append(actions, action{kind: "commit"})
314→		}
315→	}
316→	return actions
317→}
318→
319→func hasCreate(actions []action) bool {
320→	for _, a := range actions {
321→		if a.kind == "create" {
322→			return true
323→		}
324→	}
325→	return false
326→}
327→
328→func hasModify(actions []action) bool {
329→	for _, a := range actions {
330→		if a.kind == "modify" {
331→			return true
332→		}
333→	}
334→	return false
335→}
336→
337→func hasModifyOnly(actions []action) bool {
338→	if len(actions) == 0 {
339→		return false
340→	}
341→	for _, a := range actions {
342→		if a.kind != "modify" {
343→			return false
344→		}
345→	}
346→	return true
347→}
348→
349→// interleaveCommits inserts a commit after each create/modify action.
350→func interleaveCommits(actions []action) []action {
351→	var result []action
352→	for _, a := range actions {
353→		result = append(result, a)
354→		if a.kind == "create" || a.kind == "modify" {
355→			result = append(result, action{kind: "commit"})
356→		}
357→	}
358→	return result
359→}
360→
361→func extractTopic(prompt string) string {
362→	// "about the colour red" → "the colour red"
363→	re := regexp.MustCompile(`(?i)about\s+(.+?)(?:\.|,|\s+Do\s|\s+do\s|\s+then\s|$)`)
364→	if m := re.FindStringSubmatch(prompt); m != nil {
365→		return strings.TrimSpace(m[1])
366→	}
367→	return "the topic"
368→}
369→
370→func executeActions(dir string, actions []action) {
371→	for _, a := range actions {
372→		switch a.kind {
373→		case "create":
374→			createFile(dir, a.path, a.content)
375→		case "modify":
376→			modifyFile(dir, a.path, a.content)
377→		case "delete":
378→			deleteFile(dir, a.path)
379→		case "commit":
380→			gitCommit(dir)
381→		}
382→	}
383→}
384→
385→func createFile(dir, path, content string) {
386→	abs := filepath.Join(dir, path)
387→	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
388→		fmt.Fprintf(os.Stderr, "mkdir %s: %v\n", filepath.Dir(abs), err)
389→		return
390→	}
391→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
392→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
393→	}
394→}
395→
396→func modifyFile(dir, path, appendContent string) {
397→	abs := filepath.Join(dir, path)
398→	existing, _ := os.ReadFile(abs)
399→	content := string(existing) + "\n" + appendContent
400→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
401→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
402→	}
403→}
404→
405→func deleteFile(dir, path string) {
406→	abs := filepath.Join(dir, path)
407→	if err := os.Remove(abs); err != nil {
408→		fmt.Fprintf(os.Stderr, "remove %s: %v\n", abs, err)
409→	}
410→}
411→
412→func gitCommit(dir string) {
413→	gitRun(dir, "add", ".")
414→	gitRun(dir, "commit", "-m", "Fake agent commit")
415→}
416→
417→func gitRun(dir string, args ...string) {
418→	cmd := exec.Command("git", args...)
419→	cmd.Dir = dir
420→	cmd.Stdout = os.Stdout
421→	cmd.Stderr = os.Stderr
422→	// Signal that this is a non-interactive agent — git hooks should not
423→	// attempt TTY prompts. GIT_TERMINAL_PROMPT is the standard git env var
424→	// for this (same approach used by Factory AI Droid).
425→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
426→	if err := cmd.Run(); err != nil {
427→		fmt.Fprintf(os.Stderr, "git %s: %v\n", strings.Join(args, " "), err)
428→	}
429→}
430→
431→// --- Hook Firing ---
432→
433→func fireHook(dir, hookName string, payload any) {
434→	data, err := json.Marshal(payload)
435→	if err != nil {
436→		fmt.Fprintf(os.Stderr, "marshal hook payload: %v\n", err)
437→		return
438→	}
439→
440→	cmd := exec.Command("entire", "hooks", "fake", hookName)
441→	cmd.Dir = dir
442→	cmd.Stdin = bytes.NewReader(data)
443→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
444→	// Capture output but don't show it — hooks may output banners
445→	out, err := cmd.CombinedOutput()
446→	if err != nil {
447→		fmt.Fprintf(os.Stderr, "hook %s failed: %v\n%s\n", hookName, err, out)
448→	}
449→}
450→
451→// --- Transcript ---
452→
453→func setupTranscript(_, sessionID string) string {
454→	home, err := os.UserHomeDir()
455→	if err != nil {
456→		fatal("home dir: %v", err)
457→	}
458→	transcriptDir := filepath.Join(home, ".fakeagent", "sessions")
459→	if err := os.MkdirAll(transcriptDir, 0o755); err != nil {
460→		fatal("mkdir transcript dir: %v", err)
461→	}
462→	path := filepath.Join(transcriptDir, sessionID+".jsonl")
463→	// Create empty file
464→	if err := os.WriteFile(path, nil, 0o644); err != nil {
465→		fatal("create transcript: %v", err)
466→	}
467→	return path
468→}
469→
470→type transcriptEntry struct {
471→	Type      string `json:"type"`
472→	Timestamp string `json:"timestamp"`
473→	Message   string `json:"message"`
474→}
475→
476→func appendTranscript(path, role, content string) {
477→	entry := transcriptEntry{
478→		Type:      role,
479→		Timestamp: time.Now().Format(time.RFC3339),
480→		Message:   content,
481→	}
482→	data, _ := json.Marshal(entry) //nolint:errchkjson // transcriptEntry has no unsafe types
483→	data = append(data, '\n')
484→
485→	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o644)
486→	if err != nil {
487→		return
488→	}
489→	defer f.Close()
490→	f.Write(data)
491→}
492→
493→func fatal(format string, args ...any) {
494→	fmt.Fprintf(os.Stderr, "fakeagent: "+format+"\n", args...)
495→	os.Exit(1)
496→}
